1	-- 变电站倒闸操作票与防误闭锁服务建表脚本（H2，MODE=MySQL）
2	-- 时间列统一为 UTC 时间戳（TIMESTAMP），由应用层 Clock 写入。
3	
4	CREATE TABLE IF NOT EXISTS switching_ticket (
5	    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
6	    request_id   VARCHAR(64)  NOT NULL,
7	    interval_id  VARCHAR(64)  NOT NULL,
8	    title        VARCHAR(128) NOT NULL,
9	    status       VARCHAR(16)  NOT NULL,
10	    reviewer_id  VARCHAR(64),
11	    issued_at    TIMESTAMP,
12	    expires_at   TIMESTAMP,
13	    created_at   TIMESTAMP    NOT NULL,
14	    updated_at   TIMESTAMP    NOT NULL
15	);
16	COMMENT ON TABLE switching_ticket IS '倒闸操作票主表';
17	COMMENT ON COLUMN switching_ticket.id IS '主键，自增';
18	COMMENT ON COLUMN switching_ticket.request_id IS '拟票幂等请求号';
19	COMMENT ON COLUMN switching_ticket.interval_id IS '间隔编号';
20	COMMENT ON COLUMN switching_ticket.title IS '操作任务名称（合成数据）';
21	COMMENT ON COLUMN switching_ticket.status IS '状态：DRAFT拟票/REVIEWED已审核/ISSUED已预发/EXECUTING执行中/ARCHIVED已归档(终态)/EXCEPTION异常中止/EXPIRED已作废';
22	COMMENT ON COLUMN switching_ticket.reviewer_id IS '审核人编号，未审核为空';
23	COMMENT ON COLUMN switching_ticket.issued_at IS '预发时刻（UTC），未预发为空';
24	COMMENT ON COLUMN switching_ticket.expires_at IS '作废时刻（UTC）=预发+24小时，恰满即作废，未预发为空';
25	COMMENT ON COLUMN switching_ticket.created_at IS '创建时刻（UTC）';
26	COMMENT ON COLUMN switching_ticket.updated_at IS '最近更新时刻（UTC）';
27	
28	CREATE TABLE IF NOT EXISTS switching_step (
29	    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
30	    ticket_id      BIGINT      NOT NULL,
31	    seq            INT         NOT NULL,
32	    operation_type VARCHAR(32) NOT NULL,
33	    device_id      VARCHAR(64) NOT NULL,
34	    expected_state VARCHAR(16) NOT NULL,
35	    status         VARCHAR(16) NOT NULL,
36	    operator_id    VARCHAR(64),
37	    guardian_id    VARCHAR(64),
38	    executed_at    TIMESTAMP,
39	    verified       BOOLEAN     NOT NULL DEFAULT FALSE,
40	    CONSTRAINT uk_step_ticket_seq UNIQUE (ticket_id, seq)
41	);
42	COMMENT ON TABLE switching_step IS '操作票步骤表，逐项执行轨迹可复算';
43	COMMENT ON COLUMN switching_step.ticket_id IS '所属操作票主键';
44	COMMENT ON COLUMN switching_step.seq IS '步序，从1开始，票内唯一';
45	COMMENT ON COLUMN switching_step.operation_type IS '操作类型：OPEN_BREAKER/CLOSE_BREAKER/OPEN_DISCONNECTOR/CLOSE_DISCONNECTOR/APPLY_GROUND/REMOVE_GROUND/BUS_OUTAGE';
46	COMMENT ON COLUMN switching_step.device_id IS '操作设备编号';
47	COMMENT ON COLUMN switching_step.expected_state IS '该步预期设备状态：OPEN/CLOSED/APPLIED/REMOVED/OUTAGE';
48	COMMENT ON COLUMN switching_step.status IS '步骤状态：PENDING待执行/DONE已执行';
49	COMMENT ON COLUMN switching_step.operator_id IS '操作人编号，未执行为空';
50	COMMENT ON COLUMN switching_step.guardian_id IS '监护人编号，未执行为空，必须与操作人不同';
51	COMMENT ON COLUMN switching_step.executed_at IS '执行时刻（UTC），未执行为空';
52	COMMENT ON COLUMN switching_step.verified IS '遥信是否已回报核对一致';
53	
54	CREATE TABLE IF NOT EXISTS device_state (
55	    device_id   VARCHAR(64) PRIMARY KEY,
56	    interval_id VARCHAR(64) NOT NULL,
57	    device_type VARCHAR(16) NOT NULL,
58	    state       VARCHAR(16) NOT NULL,
59	    updated_at  TIMESTAMP   NOT NULL
60	);
61	COMMENT ON TABLE device_state IS '间隔设备实时状态表（合成数据）';
62	COMMENT ON COLUMN device_state.device_id IS '设备编号';
63	COMMENT ON COLUMN device_state.interval_id IS '所属间隔编号';
64	COMMENT ON COLUMN device_state.device_type IS '设备类型：BREAKER开关/DISCONNECTOR刀闸/GROUND接地线/BUS母线';
65	COMMENT ON COLUMN device_state.state IS '设备状态：OPEN分/CLOSED合/APPLIED已挂/REMOVED已拆/ENERGIZED带电/OUTAGE停电';
66	COMMENT ON COLUMN device_state.updated_at IS '状态更新时刻（UTC）';
67	
68	CREATE TABLE IF NOT EXISTS interlock_rule (
69	    rule_code   VARCHAR(64) PRIMARY KEY,
70	    description VARCHAR(256) NOT NULL,
71	    enabled     BOOLEAN      NOT NULL DEFAULT TRUE
72	);
73	COMMENT ON TABLE interlock_rule IS '防误闭锁规则库（合成数据）';
74	COMMENT ON COLUMN interlock_rule.rule_code IS '规则编码';
75	COMMENT ON COLUMN interlock_rule.description IS '规则中文说明';
76	COMMENT ON COLUMN interlock_rule.enabled IS '是否启用';
77	
78	CREATE TABLE IF NOT EXISTS interlock_hit (
79	    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
80	    ticket_id  BIGINT,
81	    step_seq   INT,
82	    rule_code  VARCHAR(64)  NOT NULL,
83	    detail     VARCHAR(512) NOT NULL,
84	    created_at TIMESTAMP    NOT NULL
85	);
86	COMMENT ON TABLE interlock_hit IS '闭锁命中记录，可复算';
87	COMMENT ON COLUMN interlock_hit.ticket_id IS '关联操作票主键，可为空（解锁等场景）';
88	COMMENT ON COLUMN interlock_hit.step_seq IS '关联步序，可为空';
89	COMMENT ON COLUMN interlock_hit.rule_code IS '命中的闭锁规则编码';
90	COMMENT ON COLUMN interlock_hit.detail IS '命中详情';
91	COMMENT ON COLUMN interlock_hit.created_at IS '命中时刻（UTC）';
92	
93	CREATE TABLE IF NOT EXISTS idempotent_request (
94	    request_id    VARCHAR(64) PRIMARY KEY,
95	    endpoint      VARCHAR(64)  NOT NULL,
96	    fingerprint   VARCHAR(64)  NOT NULL,
97	    response_body CLOB         NOT NULL,
98	    http_status   INT          NOT NULL,
99	    created_at    TIMESTAMP    NOT NULL
100	);
101	COMMENT ON TABLE idempotent_request IS '幂等请求登记表，指纹覆盖requestId与全部业务字段';
102	COMMENT ON COLUMN idempotent_request.request_id IS '幂等请求号';
103	COMMENT ON COLUMN idempotent_request.endpoint IS '接口标识';
104	COMMENT ON COLUMN idempotent_request.fingerprint IS '请求指纹SHA-256，覆盖requestId与全部业务字段';
105	COMMENT ON COLUMN idempotent_request.response_body IS '首次响应报文快照（JSON）';
106	COMMENT ON COLUMN idempotent_request.http_status IS '首次响应HTTP状态码';
107	COMMENT ON COLUMN idempotent_request.created_at IS '登记时刻（UTC）';
108	
109	CREATE TABLE IF NOT EXISTS interval_execution_lock (
110	    interval_id VARCHAR(64) PRIMARY KEY,
111	    ticket_id   BIGINT    NOT NULL,
112	    acquired_at TIMESTAMP NOT NULL
113	);
114	COMMENT ON TABLE interval_execution_lock IS '间隔执行锁，同一间隔同时刻仅允许一张执行中操作票';
115	COMMENT ON COLUMN interval_execution_lock.interval_id IS '间隔编号';
116	COMMENT ON COLUMN interval_execution_lock.ticket_id IS '持有锁的操作票主键';
117	COMMENT ON COLUMN interval_execution_lock.acquired_at IS '加锁时刻（UTC）';
118	
119	CREATE TABLE IF NOT EXISTS telemetry (
120	    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
121	    interval_id VARCHAR(64) NOT NULL,
122	    device_id   VARCHAR(64) NOT NULL,
123	    ts          TIMESTAMP   NOT NULL,
124	    state       VARCHAR(16) NOT NULL,
125	    late        BOOLEAN     NOT NULL DEFAULT FALSE,
126	    created_at  TIMESTAMP   NOT NULL,
127	    CONSTRAINT uk_telemetry_interval_ts UNIQUE (interval_id, ts)
128	);
129	COMMENT ON TABLE telemetry IS '遥信回报表，按间隔+时标去重';
130	COMMENT ON COLUMN telemetry.interval_id IS '间隔编号';
131	COMMENT ON COLUMN telemetry.device_id IS '设备编号';
132	COMMENT ON COLUMN telemetry.ts IS '遥信时标（UTC）';
133	COMMENT ON COLUMN telemetry.state IS '回报状态：OPEN/CLOSED/APPLIED/REMOVED/OUTAGE';
134	COMMENT ON COLUMN telemetry.late IS '是否迟到遥信（票已归档后到达，仅记录不处理）';
135	COMMENT ON COLUMN telemetry.created_at IS '入库时刻（UTC）';
136	
137	CREATE TABLE IF NOT EXISTS unlock_record (
138	    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
139	    device_id    VARCHAR(64)  NOT NULL,
140	    rule_code    VARCHAR(64)  NOT NULL,
141	    authorizer_a VARCHAR(64)  NOT NULL,
142	    authorizer_b VARCHAR(64)  NOT NULL,
143	    reason       VARCHAR(256) NOT NULL,
144	    action       VARCHAR(16)  NOT NULL,
145	    created_at   TIMESTAMP    NOT NULL
146	);
147	COMMENT ON TABLE unlock_record IS '紧急解锁留痕表，解锁与闭锁恢复同一事务成对写入';
148	COMMENT ON COLUMN unlock_record.device_id IS '解锁设备编号';
149	COMMENT ON COLUMN unlock_record.rule_code IS '被解锁的闭锁规则编码';
150	COMMENT ON COLUMN unlock_record.authorizer_a IS '授权人甲编号';
151	COMMENT ON COLUMN unlock_record.authorizer_b IS '授权人乙编号，必须与甲不同';
152	COMMENT ON COLUMN unlock_record.reason IS '解锁原因，非空';
153	COMMENT ON COLUMN unlock_record.action IS '动作：UNLOCK解锁/RESTORE闭锁恢复';
154	COMMENT ON COLUMN unlock_record.created_at IS '记录时刻（UTC）';
155	
156	CREATE TABLE IF NOT EXISTS ground_wire (
157	    code               VARCHAR(64) PRIMARY KEY,
158	    status             VARCHAR(32) NOT NULL,
159	    interval_id        VARCHAR(64),
160	    occupied_by_ticket BIGINT,
161	    version            INT         NOT NULL DEFAULT 1,
162	    created_at         TIMESTAMP   NOT NULL,
163	    updated_at         TIMESTAMP   NOT NULL
164	);
165	COMMENT ON TABLE ground_wire IS '合成实物接地线台账，每条编号全局唯一，同一实物同一时刻最多被一张操作票占用';
166	COMMENT ON COLUMN ground_wire.code IS '接地线唯一编号（合成数据，如JDX-1001）';
167	COMMENT ON COLUMN ground_wire.status IS '实物状态：AVAILABLE可用/BORROWED借出/APPLIED已挂接/REMOVED_PENDING_RETURN已拆除待归还';
168	COMMENT ON COLUMN ground_wire.interval_id IS '当前占用票所属间隔编号；可用或已归还后为空';
169	COMMENT ON COLUMN ground_wire.occupied_by_ticket IS '当前占用该实物的操作票主键；可用或已归还后为空';
170	COMMENT ON COLUMN ground_wire.version IS '乐观版本号，从1开始，每次成功状态变更（借用/挂接/拆除/归还）加1';
171	COMMENT ON COLUMN ground_wire.created_at IS '入库时刻（UTC）';
172	COMMENT ON COLUMN ground_wire.updated_at IS '最近状态变更时刻（UTC）';
173	
174	CREATE TABLE IF NOT EXISTS ground_wire_loan (
175	    id                BIGINT AUTO_INCREMENT PRIMARY KEY,
176	    request_id        VARCHAR(64) NOT NULL,
177	    ticket_id         BIGINT      NOT NULL,
178	    interval_id       VARCHAR(64) NOT NULL,
179	    wire_code         VARCHAR(64) NOT NULL,
180	    status            VARCHAR(16) NOT NULL,
181	    borrowed_at       TIMESTAMP   NOT NULL,
182	    returned_at       TIMESTAMP,
183	    return_request_id VARCHAR(64),
184	    keeper_id         VARCHAR(64),
185	    created_at        TIMESTAMP   NOT NULL
186	);
187	COMMENT ON TABLE ground_wire_loan IS '接地线借用/归还历史，每条实物每票一行，归还后保留不删除';
188	COMMENT ON COLUMN ground_wire_loan.request_id IS '借用幂等请求号';
189	COMMENT ON COLUMN ground_wire_loan.ticket_id IS '借用绑定的操作票主键';
190	COMMENT ON COLUMN ground_wire_loan.interval_id IS '借用时间隔编号（取自操作票）';
191	COMMENT ON COLUMN ground_wire_loan.wire_code IS '接地线编号';
192	COMMENT ON COLUMN ground_wire_loan.status IS 'BORROWED占用中（含已挂接/已拆除待归还）/RETURNED已归还';
193	COMMENT ON COLUMN ground_wire_loan.borrowed_at IS '借用声明的精确操作时刻（UTC，请求occurredAt）';
194	COMMENT ON COLUMN ground_wire_loan.returned_at IS '归还核销时刻（UTC，请求occurredAt），未归还为空';
195	COMMENT ON COLUMN ground_wire_loan.return_request_id IS '归还幂等请求号，未归还为空';
196	COMMENT ON COLUMN ground_wire_loan.keeper_id IS '归还时核对编号的仓管编号，未归还为空';
197	COMMENT ON COLUMN ground_wire_loan.created_at IS '入库时刻（UTC）';
198	
199	CREATE TABLE IF NOT EXISTS ground_wire_evidence (
200	    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
201	    wire_code   VARCHAR(64) NOT NULL,
202	    ticket_id   BIGINT      NOT NULL,
203	    step_seq    INT         NOT NULL,
204	    action      VARCHAR(16) NOT NULL,
205	    operator_id VARCHAR(64) NOT NULL,
206	    guardian_id VARCHAR(64) NOT NULL,
207	    occurred_at TIMESTAMP   NOT NULL,
208	    request_id  VARCHAR(64) NOT NULL,
209	    created_at  TIMESTAMP   NOT NULL
210	);
211	COMMENT ON TABLE ground_wire_evidence IS '挂接/拆除双人确认操作证据，应用只追加写入，不更新不删除，不可覆盖';
212	COMMENT ON COLUMN ground_wire_evidence.wire_code IS '接地线编号';
213	COMMENT ON COLUMN ground_wire_evidence.ticket_id IS '所属操作票主键';
214	COMMENT ON COLUMN ground_wire_evidence.step_seq IS '挂接/拆除引用的本票步序';
215	COMMENT ON COLUMN ground_wire_evidence.action IS 'APPLIED挂接/REMOVED拆除';
216	COMMENT ON COLUMN ground_wire_evidence.operator_id IS '操作人编号，必须与监护人不同';
217	COMMENT ON COLUMN ground_wire_evidence.guardian_id IS '监护人编号，必须与操作人不同';
218	COMMENT ON COLUMN ground_wire_evidence.occurred_at IS '请求声明的精确操作时刻（UTC）';
219	COMMENT ON COLUMN ground_wire_evidence.request_id IS '幂等请求号';
220	COMMENT ON COLUMN ground_wire_evidence.created_at IS '证据入库时刻（UTC，服务端时钟）';
221	
222	CREATE UNIQUE INDEX IF NOT EXISTS uk_ground_evidence ON ground_wire_evidence (wire_code, ticket_id, step_seq, action);
223	CREATE INDEX IF NOT EXISTS idx_ground_loan_ticket ON ground_wire_loan (ticket_id);
224	CREATE INDEX IF NOT EXISTS idx_ground_loan_wire ON ground_wire_loan (wire_code);
225

