282	    @Test
283	    void concurrentIssueOnlyOneSucceedsForSameInterval() throws Exception {
284	        long ticketA = draft("r-con-a", "INT-1101", step("OPEN_BREAKER", "BR-1101", "OPEN"));
285	        long ticketB = draft("r-con-b", "INT-1101", step("OPEN_BREAKER", "BR-1101", "OPEN"));
286	        orderService.review(ticketA, new ReviewRequest("rv-a", "REV-01"));
287	        orderService.review(ticketB, new ReviewRequest("rv-b", "REV-02"));
288	
289	        ExecutorService pool = Executors.newFixedThreadPool(2);
290	        CountDownLatch ready = new CountDownLatch(2);
291	        CountDownLatch start = new CountDownLatch(1);
292	        AtomicInteger success = new AtomicInteger();
293	        AtomicInteger conflict = new AtomicInteger();
294	        Runnable issueA = () -> {
295	            ready.countDown();
296	            try {
297	                start.await();
298	            } catch (InterruptedException ie) {
299	                Thread.currentThread().interrupt();
300	                throw new RuntimeException(ie);
301	            }
302	            try {
303	                orderService.issue(ticketA, new IssueRequest("iss-con-a"));
304	                success.incrementAndGet();
305	            } catch (ApiException e) {
306	                if ("CONCURRENT_TICKET".equals(e.code())) {
307	                    conflict.incrementAndGet();
308	                }
309	            }
310	        };
311	        Runnable issueB = () -> {
312	            ready.countDown();
313	            try {
314	                start.await();
315	            } catch (InterruptedException ie) {
316	                Thread.currentThread().interrupt();
317	                throw new RuntimeException(ie);
318	            }
319	            try {
320	                orderService.issue(ticketB, new IssueRequest("iss-con-b"));
321	                success.incrementAndGet();
322	            } catch (ApiException e) {
323	                if ("CONCURRENT_TICKET".equals(e.code())) {
324	                    conflict.incrementAndGet();
325	                }
326	            }
327	        };
328	        Future<?> f1 = pool.submit(issueA);
329	        Future<?> f2 = pool.submit(issueB);
330	        assertTrue(ready.await(10, TimeUnit.SECONDS));
331	        start.countDown();
332	        f1.get(30, TimeUnit.SECONDS);
333	        f2.get(30, TimeUnit.SECONDS);
334	        pool.shutdown();
335	        assertEquals(1, success.get(), "并发预发必须唯一成功");
336	        assertEquals(1, conflict.get(), "失败方必须收到唯一冲突");
337	        assertEquals(1, jdbc.queryForObject(
338	                "SELECT COUNT(*) FROM interval_execution_lock WHERE interval_id = 'INT-1101'", Integer.class));
339	    }
