438	    // ---------- 并发：竞争借用不双占 ----------
439	
440	    @Test
441	    void concurrentBorrowNeverDoubleOccupies() throws Exception {
442	        long ticketA = draftTicket("ca", "INT-1101", new StepSpec("OPEN_BREAKER", "BR-1101", "OPEN"));
443	        long ticketB = draftTicket("cb", "INT-1102", new StepSpec("OPEN_BREAKER", "BR-1101", "OPEN"));
444	        ExecutorService pool = Executors.newFixedThreadPool(2);
445	        CountDownLatch ready = new CountDownLatch(2);
446	        CountDownLatch start = new CountDownLatch(1);
447	        AtomicInteger success = new AtomicInteger();
448	        AtomicInteger rejected = new AtomicInteger();
449	        Runnable borrowA = () -> {
450	            ready.countDown();
451	            await(start);
452	            try {
453	                borrow(ticketA, "cb-a", 1L, "JDX-1004");
454	                success.incrementAndGet();
455	            } catch (ApiException e) {
456	                if ("WIRE_NOT_AVAILABLE".equals(e.code())) {
457	                    rejected.incrementAndGet();
458	                }
459	            }
460	        };
461	        Runnable borrowB = () -> {
462	            ready.countDown();
463	            await(start);
464	            try {
465	                borrow(ticketB, "cb-b", 1L, "JDX-1004");
466	                success.incrementAndGet();
467	            } catch (ApiException e) {
468	                if ("WIRE_NOT_AVAILABLE".equals(e.code())) {
469	                    rejected.incrementAndGet();
470	                }
471	            }
472	        };
473	        Future<?> f1 = pool.submit(borrowA);
474	        Future<?> f2 = pool.submit(borrowB);
475	        assertTrue(ready.await(10, TimeUnit.SECONDS));
476	        start.countDown();
477	        f1.get(30, TimeUnit.SECONDS);
478	        f2.get(30, TimeUnit.SECONDS);
479	        pool.shutdown();
480	        assertEquals(1, success.get());
481	        assertEquals(1, rejected.get());
482	        Integer loans = jdbc.queryForObject(
483	                "SELECT COUNT(*) FROM ground_wire_loan WHERE wire_code = 'JDX-1004'", Integer.class);
484	        assertEquals(1, loans);
485	        assertNotNull(groundService.getWire("JDX-1004").wire().occupiedByTicket());
486	    }
