542	            assertFalse(wireApplied);
543	        } else {
544	            assertTrue(wireApplied);
545	            assertEquals("OPEN", jdbc.queryForObject(
546	                    "SELECT state FROM device_state WHERE device_id = 'BR-1101'", String.class));
